    "assoc.userChoiceBlocked": "Windows {list} के लिए अपना स्वयं का डिफ़ॉल्ट ऐप रखता है, और इसे केवल आप ही बदल सकते हैं — किसी ऐप्लिकेशन को अनुमति नहीं है।",
