    "help.foldingPoint2": "Ctrl+Alt+[ / ] fäller ihop eller ut allt i filen på en gång.",

    "help.terminalTitle": "Terminal",
    "help.terminalIntro": "En integrerad terminalpanel, inget separat fönster.",
