    "help.languagePoint1":
      "ملاحظہ ▸ زبان… ہر ترجمے کو اس کے اپنے نام کے تحت درج کرتا ہے، اس کے انگریزی نام کے تحت نہیں، کیونکہ \"German\" کسی ایسے شخص کی مدد نہیں کرتا جو صرف اردو پڑھتا ہے۔",
